def _build_cub_transforms():
    train_trsf = [transforms.Resize((256, 256), interpolation=InterpolationMode.BICUBIC), transforms.RandomCrop(224), transforms.RandomHorizontalFlip()]
    test_trsf = [transforms.Resize((256, 256), interpolation=InterpolationMode.BICUBIC), transforms.CenterCrop(224)]
    common_trsf = [transforms.ToTensor(), transforms.Normalize(mean=(0.485, 0.456, 0.406), std=(0.229, 0.224, 0.225))]
    return (train_trsf, test_trsf, common_trsf)

def _build_aircraft_transforms():
    train_trsf = [transforms.Resize((256, 256), interpolation=InterpolationMode.BICUBIC), transforms.RandomCrop(224), transforms.RandomHorizontalFlip()]
    test_trsf = [transforms.Resize((256, 256), interpolation=InterpolationMode.BICUBIC), transforms.CenterCrop(224)]
    common_trsf = [transforms.ConvertImageDtype(torch.float32), transforms.Normalize(mean=(0.485, 0.456, 0.406), std=(0.229, 0.224, 0.225))]
    return (train_trsf, test_trsf, common_trsf)

def _build_cars196_transforms():
    train_trsf = [transforms.Resize(224, interpolation=InterpolationMode.BICUBIC), transforms.CenterCrop(224), transforms.RandomHorizontalFlip()]
    test_trsf = [transforms.Resize(224, interpolation=InterpolationMode.BICUBIC), transforms.CenterCrop(224)]
    common_trsf = [transforms.ToTensor(), transforms.Normalize(mean=(0.0, 0.0, 0.0), std=(1.0, 1.0, 1.0))]
    return (train_trsf, test_trsf, common_trsf)
